@@ -0,0 +1,175 @@
+/**
+ * Parity test — write paths produce identical column sets (B.2).
+ *
+ * Both compute-matches.ts (background precompute) and persist-session-matches.ts
+ * (live session) must write the same 21 data columns so a match renders
+ * identically regardless of which writer saved it.
+ *
+ * 21 columns: cargo_type, load_port, discharge_port, laycan_start, laycan_end,
+ * vessel_dwt, tce_usd_per_day, distance_nm, freight_rate_usd_per_mt,
+ * freight_rate_source, vessel_name, cargo_ref, fit_percent, fit_breakdown,
+ * cargo_item_index, vessel_item_index, worksheet_json, consumption_estimated,
+ * ballast_distance_nm, breakeven_tce_usd_per_day, score.
+ */
+
+import Database from 'better-sqlite3';
+import migration032 from '@/lib/migrations/032-matches';
+import migration033 from '@/lib/migrations/033-matches-score-breakdown';
+import migration034 from '@/lib/migrations/034-matches-unique-constraint';
+import migration035 from '@/lib/migrations/035-matches-tce-distance';
+import migration036 from '@/lib/migrations/036-matches-freight-rate';
+import migration041 from '@/lib/migrations/041-matches-vessel-name';
+import migration042 from '@/lib/migrations/042-matches-fit';
+import migration044 from '@/lib/migrations/044-matches-item-index';
+import migration045 from '@/lib/migrations/045-matches-worksheet';
+import migration046 from '@/lib/migrations/046-matches-consumption-estimated';
+import migration047 from '@/lib/migrations/047-matches-ballast-distance';
+import migration050 from '@/lib/migrations/050-matches-breakeven';
+import { createMatch } from '@/lib/matching/matches-repository';
+import type { CreateMatchInput } from '@/lib/matching/matches-repository';
+
+const PARITY_COLUMNS = [
+  'cargo_type',
+  'load_port',
+  'discharge_port',
+  'laycan_start',
+  'laycan_end',
+  'vessel_dwt',
+  'tce_usd_per_day',
+  'distance_nm',
+  'freight_rate_usd_per_mt',
+  'freight_rate_source',
+  'vessel_name',
+  'cargo_ref',
+  'fit_percent',
+  'fit_breakdown',
+  'cargo_item_index',
+  'vessel_item_index',
+  'worksheet_json',
+  'consumption_estimated',
+  'ballast_distance_nm',
+  'breakeven_tce_usd_per_day',
+  'score',
+] as const satisfies ReadonlyArray<keyof ReturnType<typeof createMatch>>;
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  migration032.up(db);
+  migration033.up(db);
+  migration034.up(db);
+  migration035.up(db);
+  migration036.up(db);
+  migration041.up(db);
+  migration042.up(db);
+  migration044.up(db);
+  migration045.up(db);
+  migration046.up(db);
+  migration047.up(db);
+  migration050.up(db);
+  return db;
+}
+
+const FIXTURE_WORKSHEET = JSON.stringify({
+  readiness: {
+    openDate: '2026-07-01', laycanStart: '2026-07-05', laycanEnd: '2026-07-15',
+    distanceNm: 1200, distanceExact: true, speedKn: 13, sailingDays: 3.8,
+    arrivalDate: '2026-07-05', gapDays: 0, verdict: 'ideal',
+    explanation: 'ideal', openPosition: 'Rotterdam',
+  },
+  vessel: { draftMax: 12.5, grainCapacity: 72000, grainCapacityUnit: 'cbm', geared: false, vesselType: 'bulk carrier', flag: 'MH', built: 2015, pandi: null, classSociety: 'LR', lastCargoes: null, dwtSummer: 58000, dwcc: 55000 },
+  cargo: { weightMt: 50000, weightMtEffective: 50000, cargoType: 'BULK', loadPort: 'CNSHA', dischargePort: 'NLRTM' },
+  hardFilters: { draft: { pass: true }, crane: { pass: true }, volume: { pass: true } },
+});
+
+const FIXTURE_FIT_BREAKDOWN = JSON.stringify({
+  components: [{ factor: 'utilisation', label: 'Utilisation', weight: 19, score: 15, rationale: 'Good', bracketData: '86%' }],
+  totalWeight: 19, fitPercent: 78.5, partCargo: false, vesselClass: 'supramax',
+  sanctionsPenalty: 0, appliedCap: null,
+  inputs: { distanceNm: 1200, gapDays: 0, verdict: 'ideal', utilisation: 0.86, vesselDwt: 58000, cargoWtMax: 50000 },
+});
+
+// Full input as compute-matches.ts and persist-session-matches.ts both should write
+// after B.2 fix.
+const FULL_INPUT: CreateMatchInput = {
+  cargo_id: 'cargo-email-001',
+  vessel_id: 'vessel-email-001',
+  score: 85,
+  reason: 'Good DWT fit',
+  status: 'shortlist',
+  reason_structured: null,
+  cargo_type: 'BULK',
+  load_port: 'CNSHA',
+  discharge_port: 'NLRTM',
+  laycan_start: new Date('2026-07-05').getTime(),
+  laycan_end: new Date('2026-07-15').getTime(),
+  vessel_dwt: 58000,
+  tce_usd_per_day: 12500,
+  distance_nm: 11200,
+  freight_rate_usd_per_mt: 28.5,
+  freight_rate_source: 'estimated',
+  vessel_name: 'M/V SEAGULL 200',
+  cargo_ref: 'Grain 50,000mt CNSHA-NLRTM',
+  fit_percent: 78.5,
+  fit_breakdown: FIXTURE_FIT_BREAKDOWN,
+  cargo_item_index: 0,
+  vessel_item_index: 0,
+  worksheet_json: FIXTURE_WORKSHEET,
+  consumption_estimated: 1,
+  ballast_distance_nm: 450,
+  breakeven_tce_usd_per_day: 5500,
+};
+
+describe('write-paths parity — 21 columns', () => {
+  it('compute-matches path produces same column set as persist-session-matches path', () => {
+    const db = freshDb();
+
+    // Simulate compute-matches.ts output (after B.2 fix)
+    const computeRow = createMatch(db, { ...FULL_INPUT, user_id: 'session-compute' });
+    // Simulate persist-session-matches.ts output
+    const persistRow = createMatch(db, { ...FULL_INPUT, user_id: 'session-persist' });
+
+    for (const col of PARITY_COLUMNS) {
+      expect({ column: col, compute: computeRow[col] }).toEqual({ column: col, compute: persistRow[col] });
+    }
+  });
+
+  it('all 21 parity columns are non-null in the compute-matches path', () => {
+    const db = freshDb();
+    const row = createMatch(db, { ...FULL_INPUT, user_id: 'session-check' });
+
+    for (const col of PARITY_COLUMNS) {
+      expect({ column: col, value: row[col] }).not.toMatchObject({ column: col, value: null });
+      expect({ column: col, value: row[col] }).not.toMatchObject({ column: col, value: undefined });
+    }
+  });
+
+  it('fit_breakdown round-trips as valid JSON through both paths', () => {
+    const db = freshDb();
+    const row = createMatch(db, { ...FULL_INPUT, user_id: 'session-json' });
+    const fb = JSON.parse(row.fit_breakdown!);
+    expect(fb).toHaveProperty('fitPercent');
+    expect(fb).toHaveProperty('components');
+    expect(typeof fb.fitPercent).toBe('number');
+  });
+
+  it('worksheet_json round-trips with readiness verdict', () => {
+    const db = freshDb();
+    const row = createMatch(db, { ...FULL_INPUT, user_id: 'session-ws' });
+    const ws = JSON.parse(row.worksheet_json!);
+    expect(ws.readiness.verdict).toBe('ideal');
+  });
+
+  it('breakeven_tce_usd_per_day is stored and matches DWT class threshold', () => {
+    const db = freshDb();
+    // 58,000 DWT → supramax → $5,500/day breakeven
+    const row = createMatch(db, { ...FULL_INPUT, user_id: 'session-be' });
+    expect(row.breakeven_tce_usd_per_day).toBe(5500);
+  });
+
+  it('cargo_item_index and vessel_item_index are stored (not null)', () => {
+    const db = freshDb();
+    const row = createMatch(db, { ...FULL_INPUT, user_id: 'session-idx' });
+    expect(row.cargo_item_index).toBe(0);
+    expect(row.vessel_item_index).toBe(0);
+  });
+});
